#include "stdafx.h"#include "..\MnemoWnd.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структура надписи "Дублирование"typedef struct : public SPROLOZ  {  SValueDef* def;  char form[32];  int nAlign;  } Queue_Show;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintShow(DefinePaint)  {  QueueP(Queue_Show);  //  CShBase* sh = PipeSh;  if ( sh == NULL ) return 1;  //  SParamValue var( p->nNumber, p->def );  char text[512] = "###";  bool bReturn = q.m_pPipe->FillValue( text, var, p->nFloat, p->form );  ::DrawText( hDC, text, lstrlen(text), &p->mRect, DT_SINGLELINE|p->nAlign );  //  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddShow(DefineTegs)  {  //ASS(0);	  //MIHAIL  //  AddQueueEx(Queue_Show);  //  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintShow;  //  p->nAlign = DT_VCENTER|DT_CENTER;  p->nFloat = 100;   char szObj  [32] = "\0";  char szShift[64] = "\0";  //  STegObj obj[] =    {    { 'S', "shift" , szShift,63},    { 'S', "obj"   , szObj  ,31},    { 'S', "format", p->form,31},    { 'W', "a"    , &p->nAlign },    { 'W', "align", &p->nAlign },    // Дополнительная информация    EXT_QUEUE    };  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  //  UINT eData = TextToType( szObj );  //  if ( *szShift == 0 )    {    lstrcpy( szShift, teg[0].value );    lstrcpy( teg[0].value, "." );    p->nNumber = def.GetActiveObj();    }  else    {    STeg tag;    int nTag = ::FindTeg( teg[0].value, tag, EDataTypes(eData) );    if ( nTag >= 0 ) eData = tag.tegType;    if ( eData == id_Unknown )      {      //Надо копаться в модели      eData = id_Sensor;      }    p->nNumber = def.AddKindEx( eData, teg[0].value );    }  eData = def.GetMnemoType(p->nNumber);  p->def = ::NameToValue( eData, szShift );  ASSERT( p->def !=  NULL );  //  if ( p->nFloat != 100 ) return;  if ( p->def == NULL   ) return;  //  if ( p->def->eVal == enumValueDbl )    p->nFloat = 0;  else  if ( p->def->eVal == enumValueChr )    {    //Sergej13 p->nFloat = ::NameToString( szShift, 0, NULL );    if ( p->nFloat == -1 ) p->nFloat = 8;//FLAGS;    }  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~